#!/bin/bash
# Disposable Common Ground instance for the end-to-end browser suite.
#
#   e2e/instance.sh build    type-check, lint and build the frontend (like
#                            selfhost.sh build; needs ~4 GB RAM) and the
#                            cg-e2e/* images from this checkout. Writes the
#                            checkout's node_modules/ and build/.
#   e2e/instance.sh up       start the instance (fresh secrets, fresh volumes)
#   e2e/instance.sh down     stop it, delete its volumes, generated files and
#                            the builder's yarn-cache volume
#   e2e/instance.sh status   docker compose ps
#   e2e/instance.sh logs [service...]
#
# Only the local Docker daemon is used: a non-default Docker context (or
# DOCKER_HOST) is refused unless --allow-context is given.
#
# The instance is the self-host profile (docker-compose.selfhost.yml + calls)
# plus e2e/docker-compose.e2e.yml: own compose project (E2E_PROJECT, default
# cg-e2e), own image tags (E2E_IMAGE_PREFIX, default cg-e2e), Caddy with its
# local CA (CG_TLS_MODE=internal) on the domain E2E_DOMAIN (default
# cg-e2e.test), reachable only from containers on the stack's network —
# which is where e2e/run.sh puts the browser. No host ports are published.
#
# Run the suite against it with:  e2e/run.sh --instance
set -euo pipefail

E2E_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$E2E_DIR/.." && pwd)"
DOCKER_DIR="$REPO_ROOT/docker"
STATE_DIR="$E2E_DIR/.instance"
ENV_FILE="$STATE_DIR/env"
PROJECT="${E2E_PROJECT:-cg-e2e}"
PREFIX="${E2E_IMAGE_PREFIX:-cg-e2e}"
DOMAIN="${E2E_DOMAIN:-cg-e2e.test}"
# the node builder image (docker/node): E2E_BUILDER_IMAGE, else the dev
# stack's commonground/node if present (only run, never retagged), else built
# from docker/node as $PREFIX/node
BUILDER_IMAGE="${E2E_BUILDER_IMAGE:-}"
if [ -z "$BUILDER_IMAGE" ]; then
  if docker image inspect commonground/node >/dev/null 2>&1; then
    BUILDER_IMAGE=commonground/node
  else
    BUILDER_IMAGE="$PREFIX/node"
  fi
fi

ALLOW_CONTEXT=false
ARGS=()
for arg in "$@"; do
  if [ "$arg" = "--allow-context" ]; then
    ALLOW_CONTEXT=true
  else
    ARGS+=("$arg")
  fi
done
set -- "${ARGS[@]+"${ARGS[@]}"}"
CONTEXT="$(docker context show 2>/dev/null || echo default)"
if [ "$ALLOW_CONTEXT" != true ] && { [ "$CONTEXT" != "default" ] || [ -n "${DOCKER_HOST:-}" ]; }; then
  echo "Docker context is '${CONTEXT}'${DOCKER_HOST:+ (DOCKER_HOST=$DOCKER_HOST)}, not the local default:" >&2
  echo "the disposable instance would be built and started there. Pass --allow-context if that is intended." >&2
  exit 1
fi

if [ "$PROJECT" = "docker" ] || [ "$PROJECT" = "cg-selfhost" ]; then
  echo "E2E_PROJECT=$PROJECT would hit the dev stack or a real self-host instance; pick another name." >&2
  exit 1
fi

export E2E_IMAGE_PREFIX="$PREFIX"

compose() {
  COMPOSE_PROFILES="calls" docker compose \
    -p "$PROJECT" \
    --env-file "$ENV_FILE" \
    -f "$DOCKER_DIR/docker-compose.selfhost.yml" \
    -f "$DOCKER_DIR/docker-compose.selfhost.calls.yml" \
    -f "$E2E_DIR/docker-compose.e2e.yml" \
    "$@"
}

rand() { openssl rand -hex "$1"; }

generate_env() {
  mkdir -p "$STATE_DIR"
  # fresh secrets every time: the volumes are throwaway as well
  cat > "$ENV_FILE" <<EOF
# Generated by e2e/instance.sh — throwaway, regenerated on every "up".
CG_DOMAIN=${DOMAIN}
CG_TLS_MODE=internal
CG_ACME_EMAIL=
CG_PUBLIC_IP=127.0.0.1
PASSKEY_RP_ID=
CG_LEGACY_CGID=false
CG_ID_DOMAIN=
PG_SU_PASSWORD=$(rand 24)
PG_WRITER_PASSWORD=$(rand 24)
PG_READER_PASSWORD=$(rand 24)
PG_MEDIASOUP_PASSWORD=$(rand 24)
REDIS_PASSWORD=$(rand 24)
REDIS_SECRET=$(rand 24)
S3_SECRET=$(rand 48)
REDIS_MAXMEMORY=256mb
REDIS_CACHE_MAXMEMORY=64mb
SEAWEED_VOLUME_LIMIT_MB=256
MEDIASOUP_DISABLE_LIBURING=true
CG_ENABLE_CALLS=true
CG_ENABLE_BLOCKCHAIN=false
CG_ENABLE_IMAGE_FILTER=true
CG_ENABLE_MAIL=false
PLATFORM_OPERATOR_USER_IDS=
CAPTCHA_PROVIDER=altcha
ALTCHA_HMAC_KEY=$(rand 32)
CG_RECAPTCHA_SITE_KEY=
GOOGLE_RECAPTCHA_SECRET_KEY=
# mail goes to the mailpit catcher (docker-compose.e2e.yml)
SMTP_HOST=mailpit
SMTP_PORT=1025
SMTP_SECURITY=none
SMTP_USER=
SMTP_PASSWORD=
EMAIL_FROM=no-reply@${DOMAIN}
EMAIL_FROM_NAME=Common Ground e2e
CG_ACTIVE_CHAINS=
CG_GIPHY_API_KEY=
# Empty: the frontend falls back to its built-in WalletConnect project id, so
# the wallet modal's QR views really render (they need the WalletConnect relay,
# i.e. internet access from the runner). Set E2E_WALLETCONNECT_PROJECT_ID to
# test with an instance-specific id.
CG_WALLETCONNECT_PROJECT_ID=${E2E_WALLETCONNECT_PROJECT_ID:-}
TWITTER_API_KEY=
TWITTER_API_SECRET=
TWITTER_CALLBACK_URL=
TWITTER_OAUTH2_CLIENT_ID=
TWITTER_OAUTH2_CLIENT_SECRET=
QUIKNODE_ETH=
QUIKNODE_BSC=
QUIKNODE_MATIC=
QUIKNODE_XDAI=
QUIKNODE_FANTOM=
QUIKNODE_AVAX=
QUIKNODE_ARBITRUM=
QUIKNODE_OPTIMISM=
QUIKNODE_BASE=
INFURA_LINEA=
QUIKNODE_ARBITRUM_NOVA=
QUIKNODE_CELO=
QUIKNODE_POLYGON_ZKEVM=
QUIKNODE_SCROLL=
QUIKNODE_ZKSYNC=
QUIKNODE_LUKSO=
EOF
}

generate_support_files() {
  # S3 identities (embeds S3_SECRET, so regenerated with every env)
  cat > "$STATE_DIR/s3.json" <<EOF
{
  "identities": [
    { "name": "anonymous", "actions": ["Read:cg-media"] },
    {
      "name": "cg_admin_user",
      "credentials": [
        { "accessKey": "cgadmin", "secretKey": "$(grep '^S3_SECRET=' "$ENV_FILE" | cut -d= -f2)" }
      ],
      "actions": ["Admin", "Read", "List", "Tagging", "Write"]
    }
  ]
}
EOF
  # web-push VAPID pair (P-256, base64url raw keys)
  docker run --rm -i "$PREFIX/backend" node - > "$STATE_DIR/vapid_keys.json" <<'EOF'
const { generateKeyPairSync } = require("node:crypto");
const { publicKey, privateKey } = generateKeyPairSync("ec", { namedCurve: "P-256" });
const pubJwk = publicKey.export({ format: "jwk" });
const privJwk = privateKey.export({ format: "jwk" });
const pub = Buffer.concat([Buffer.from([4]), Buffer.from(pubJwk.x, "base64url"), Buffer.from(pubJwk.y, "base64url")]);
console.log(JSON.stringify({
  publicKey: pub.toString("base64url"),
  privateKey: Buffer.from(privJwk.d, "base64url").toString("base64url"),
  subject: "mailto:e2e@invalid.example",
}, null, 2));
EOF
  # mediasoup's own HTTPS/WSS listener (Caddy in front of it does not check it)
  mkdir -p "$STATE_DIR/certs"
  openssl req -x509 -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 \
    -keyout "$STATE_DIR/certs/server.key" -out "$STATE_DIR/certs/server.crt" \
    -days 30 -nodes -subj "/CN=mediasoup.e2e.invalid" 2>/dev/null
  chmod 644 "$STATE_DIR/certs/server.key"
}

build() {
  local ctx="$STATE_DIR/build"
  rm -rf "$ctx" && mkdir -p "$ctx"

  if ! docker image inspect "$BUILDER_IMAGE" >/dev/null 2>&1; then
    echo "--- building the node builder image ($BUILDER_IMAGE)"
    docker build -t "$BUILDER_IMAGE" \
      --build-arg BUILDER_UID="$(id -u)" --build-arg BUILDER_GID="$(id -g)" "$DOCKER_DIR/node"
  fi

  echo "--- frontend: yarn install, typecheck, lint, vite build, HTML check (in $BUILDER_IMAGE)"
  # the same checks as selfhost.sh build; the yarn cache lives in a named
  # volume (its mount point is owned by the builder user in the image, so the
  # fresh volume is too); node_modules/ and build/ go into the checkout like
  # with ./run.sh build_full
  docker run --rm -u "$(id -u):$(id -g)" \
    -v "$REPO_ROOT:/cg" -v "${PROJECT}-yarn-cache:/builder-cache" \
    -e YARN_CACHE_FOLDER=/builder-cache -e YARN_ENABLE_GLOBAL_CACHE=false \
    -e NODE_OPTIONS=--max-old-space-size=4096 -e DEPLOYMENT=prod \
    -w /cg "$BUILDER_IMAGE" bash -c "yarn install --immutable && yarn typecheck && yarn lint && yarn build && yarn check:html-rewrite"

  echo "--- edge image ($PREFIX/caddy)"
  mkdir -p "$ctx/caddy"
  cp "$DOCKER_DIR"/caddy/{Dockerfile,common.caddy,Caddyfile.dev,Caddyfile.selfhost,instance-config.js} "$ctx/caddy/"
  cp -r "$REPO_ROOT/build" "$ctx/caddy/dist"
  docker build -t "$PREFIX/caddy" "$ctx/caddy"

  echo "--- backend images ($PREFIX/backend_stage_0, $PREFIX/backend)"
  mkdir -p "$ctx/backend"
  cp "$DOCKER_DIR"/backend/*.sh "$DOCKER_DIR"/backend/Dockerfile_dev_stage_* "$ctx/backend/"
  rsync -aL --exclude=node_modules --exclude=.yarn "$REPO_ROOT/srv/" "$ctx/backend/dist/"
  cp "$REPO_ROOT/build/index.html" "$ctx/backend/dist/"
  docker build -t "$PREFIX/backend_stage_0" -f "$ctx/backend/Dockerfile_dev_stage_0" "$ctx/backend"
  sed "s#^FROM commonground/backend_stage_0#FROM $PREFIX/backend_stage_0#" \
    "$ctx/backend/Dockerfile_dev_stage_1" > "$ctx/backend/Dockerfile.e2e"
  # the frontend build's ID (vite/buildId.ts), as selfhost.sh build does
  docker build -t "$PREFIX/backend" --build-arg CG_BUILD_ID="$(cat "$REPO_ROOT/build/build-id.txt")" \
    -f "$ctx/backend/Dockerfile.e2e" "$ctx/backend"

  echo "--- database image ($PREFIX/db)"
  docker build -t "$PREFIX/db" "$DOCKER_DIR/db"

  rm -rf "$ctx"
  echo "--- done. Start the instance with: e2e/instance.sh up"
}

wait_ready() {
  echo "waiting for migrations..."
  compose wait migrate-db >/dev/null 2>&1 || true
  if [ "$(docker inspect -f '{{.State.ExitCode}}' "${PROJECT}-migrate-db-1")" != "0" ]; then
    echo "migrate-db failed:" >&2
    compose logs migrate-db | tail -30 >&2
    return 1
  fi
  echo "waiting for the edge and the API..."
  for _ in $(seq 1 90); do
    if export_ca >/dev/null 2>&1 && compose exec -T caddy \
         wget -q -O /dev/null --no-check-certificate \
         "https://${DOMAIN}/api/v2/Instance/config" >/dev/null 2>&1; then
      echo "instance is up: https://${DOMAIN} (project ${PROJECT}, network ${PROJECT}_cryptogram)"
      return 0
    fi
    sleep 2
  done
  echo "the instance did not come up within 180s:" >&2
  compose ps >&2
  return 1
}

# removes the compose project's containers, volumes and network by name —
# with a throwaway env file when the generated one is gone (compose needs the
# variables to read the files)
remove_stack() {
  if [ -z "$(docker ps -aq --filter "label=com.docker.compose.project=${PROJECT}")" ] &&
     [ -z "$(docker volume ls -q --filter "label=com.docker.compose.project=${PROJECT}")" ]; then
    return 0
  fi
  [ -f "$ENV_FILE" ] || generate_env
  compose down -v --remove-orphans
}

# the root of Caddy's local CA, for the suite (--ca)
export_ca() {
  compose exec -T caddy cat /data/caddy/pki/authorities/local/root.crt > "$STATE_DIR/root.crt.tmp" &&
    [ -s "$STATE_DIR/root.crt.tmp" ] && mv "$STATE_DIR/root.crt.tmp" "$STATE_DIR/root.crt"
}

case "${1:-}" in
  build)
    build
    ;;
  up)
    for image in caddy backend db; do
      if ! docker image inspect "$PREFIX/$image" >/dev/null 2>&1; then
        echo "image $PREFIX/$image is missing — run e2e/instance.sh build first" >&2
        exit 1
      fi
    done
    # always from clean volumes: whatever an earlier run left under this
    # project name goes first (also without its env file)
    remove_stack
    generate_env
    generate_support_files
    compose up -d
    wait_ready
    ;;
  down)
    remove_stack
    rm -rf "$STATE_DIR"
    docker volume rm "${PROJECT}-yarn-cache" >/dev/null 2>&1 || true
    echo "e2e instance ${PROJECT} removed (containers, volumes, generated files, yarn cache)."
    ;;
  status)
    if [ -n "$(docker ps -aq --filter "label=com.docker.compose.project=${PROJECT}")" ]; then
      [ -f "$ENV_FILE" ] || generate_env
      compose ps
    else
      echo "no e2e instance (compose project ${PROJECT}) - start one with e2e/instance.sh up"
    fi
    ;;
  logs)
    compose logs --tail=200 "${@:2}"
    ;;
  ca)
    export_ca && echo "$STATE_DIR/root.crt"
    ;;
  compose)
    compose "${@:2}"
    ;;
  *)
    sed -n '2,16p' "$0" | sed 's/^# \{0,1\}//'
    exit 1
    ;;
esac
